create table public.cineo_traffic(day date primary key,requests bigint not null default 0,request_bytes bigint not null default 0,response_bytes bigint not null default 0); alter table public.cineo_traffic enable row level security; revoke all on public.cineo_traffic from anon,authenticated; grant all on public.cineo_traffic to service_role; create function public.cineo_count_traffic(incoming bigint,outgoing bigint) returns void language sql security invoker set search_path='' as $$insert into public.cineo_traffic(day,requests,request_bytes,response_bytes) values(current_date,1,greatest(0,incoming),greatest(0,outgoing)) on conflict(day) do update set requests=public.cineo_traffic.requests+1,request_bytes=public.cineo_traffic.request_bytes+excluded.request_bytes,response_bytes=public.cineo_traffic.response_bytes+excluded.response_bytes$$; revoke all on function public.cineo_count_traffic(bigint,bigint) from public,anon,authenticated; grant execute on function public.cineo_count_traffic(bigint,bigint) to service_role;
